require( "luaunit" )
require( "luaunit_extensions" )
require( "luaunitmockworktable" )
require( "luaunitmockkernel" )

dofile( "../data-store-functions.lua" )
dofile( "../inventory-functions.lua" )
dofile( "../shopping-cart-genre-categories.lua" )

local test_datastoreget_index
local test_datastoreget

local now = { year = 2009, month = 11, day = 06, hour = 9, min = 30, sec = 0 }
local now_string = string.format( "%4d%02d%02d%02d%02d%02d", now.year, now.month, now.day, now.hour, now.min, now.sec )
local now_plus_28_days = { year = 2009, month = 12, day = 04, hour = 9, min = 30, sec = 0 }
local now_plus_28_days_string = string.format( "%4d%02d%02d%02d%02d%02d", now_plus_28_days.year, now_plus_28_days.month, now_plus_28_days.day, now_plus_28_days.hour, now_plus_28_days.min, now_plus_28_days.sec )

TestShoppingCartGenreCategories = {}

function TestShoppingCartGenreCategories:setUp()
	os_date_hold = os.date
	os.date = function() return now end
	kernel = newluaunitmockkernel()
	MasterProductCatalog = newluaunitmockworktable()
end

function TestShoppingCartGenreCategories:tearDown()
 	kernel = nil
	MasterProductCatalog = nil
	os.date = os_date_hold
end

function TestShoppingCartGenreCategories:test_creation_values()
	local o = newshoppingcartgenrecategories()
	assert_is_not_nil( o )
	assert_table_count( o.formats, 0 )
	assert_table_count( o.ratings, 0 )
end

function TestShoppingCartGenreCategories:test_instances_are_different()
	local o = newshoppingcartgenrecategories()
	local p = newshoppingcartgenrecategories()

	assert_not_equal(o, p)
end

function TestShoppingCartGenreCategories:test_process_nil_product_table_throws_exception()
	kernel:log_data( { message = "Product table cannot be nil!" } )
	local o = newshoppingcartgenrecategories()
	try(
		function()
			o:process( nil )
		end,
		function( e )
			assert_pattern_matches( e, "../shopping-cart-genre-categories.lua:%d%d: Product table cannot be nil!" )
		end
	)
end

function TestShoppingCartGenreCategories:test_process_empty_product_table_throws_exception()
	kernel:log_data( { message = "Product table contains no entries!" } )
	local o = newshoppingcartgenrecategories()
	try(
		function()
			o:process( {} )
		end,
		function( e )
			assert_pattern_matches( e, "../shopping-cart-genre-categories.lua:%d%d: Product table contains no entries!" )
		end
	)
end

function TestShoppingCartGenreCategories:test_process_nil_total_throws_exception()
	kernel:log_data( { message = "Total cannot be nil!" } )
