function TestShoppingCartGenreCategories:test_g_dvd_no_coming_soon_master_product_entries()
	kernel:dateadd_data( { thedate = now, interval = "28", response = now_plus_28_days } )

	MasterProductCatalog[1] = { product_id = 1, product_type_id = 1, rating_id = 5, genres = {} }
	local o = newshoppingcartgenrecategories()
	local results = o:process( { { product_id = 1 } }, 3 )
	assert_table_count( o.formats, 1 )
	assert_true( o.formats[1] )
	assert_table_count( o.ratings, 1 )
	assert_true( o.ratings[5] )
	assert_is_not_nil( results )
	assert_table_count( results, 0 )
end

