	MasterProductCatalog[1] = { product_id = 1, product_type_id = 1, rating_id = 5, genres = {} }
	MasterProductCatalog[2] = { product_id = 2, product_type_id = 1, rating_id = 5, genres = {}, release_date = "20090101120000" }
