function TestShoppingCartGenreCategories:test_024_process_five_dvds_different_genres_all_seperate()
	MasterProductCatalog[1] = { product_id = 1, rating_id = 5, genres = { [1009] = true } }
	MasterProductCatalog[2] = { product_id = 2, rating_id = 6, genres = { [1010] = true } }
	MasterProductCatalog[3] = { product_id = 3, rating_id = 7, genres = { [1011] = true } }
	MasterProductCatalog[4] = { product_id = 4, rating_id = 8, genres = { [1012] = true } }
	MasterProductCatalog[5] = { product_id = 5, rating_id = 5, genres = { [1013] = true } }
	local o = newshoppingcartgenrecategories()
	o:process( { { product_id = 1 } } )
	assert_table_count( o.dvd.genres, 1 )
	assert_is_not_nil( o.dvd.genres[1009] )
	assert_equals( o.dvd.rating_id, 5 )
	assert_table_count( o.bluray.genres, 0 )
	assert_equals( o.bluray.rating_id, -1 )
	assert_table_count( o.game.genres, 0 )
	assert_equals( o.game.rating_id, -1 )
	o:process( { { product_id = 2 } } )
	assert_table_count( o.dvd.genres, 2 )
	assert_is_not_nil( o.dvd.genres[1009] )
	assert_is_not_nil( o.dvd.genres[1010] )
	assert_equals( o.dvd.rating_id, 5 )
	assert_table_count( o.bluray.genres, 0 )
	assert_equals( o.bluray.rating_id, -1 )
	assert_table_count( o.game.genres, 0 )
	assert_equals( o.game.rating_id, -1 )
	o:process( { { product_id = 3 } } )
	assert_table_count( o.dvd.genres, 3 )
	assert_is_not_nil( o.dvd.genres[1009] )
	assert_is_not_nil( o.dvd.genres[1010] )
	assert_is_not_nil( o.dvd.genres[1011] )
