        { store = "profile" , table_name = "ProductCatalog", key = "1", return_object = "{ product_id = 1, rating_id = 6, genres = { [1022] = true, [1009] = true } }" },
        { store = "profile" , table_name = "ProductCatalog", key = "2", return_object = "{ product_id = 2, rating_id = 8, genres = { [1022] = true, [1010] = true } }" },
        { store = "profile" , table_name = "ProductCatalog", key = "3", return_object = "{ product_id = 3, rating_id = 8, genres = { [1022] = true, [1011] = true } }" },
		{ store = "profile" , table_name = "ProductCatalog", key = "4", return_object = "" },
		{ store = "profile" , table_name = "ProductCatalog", key = "5", return_object = "" },
		{ store = "profile" , table_name = "ProductCatalog", key = "6", return_object = "" },
		{ store = "profile" , table_name = "ProductCatalog", key = "7", return_object = "" },
		{ store = "profile" , table_name = "ProductCatalog", key = "8", return_object = "" },
		{ store = "profile" , table_name = "ProductCatalog", key = "9", return_object = "" },
	}

	local o = newshoppingcartgenrecategories()

	local result

	o:process( { product_id = 1, rating_id = 6, genres = { [1022] = true, [1009] = true } } )

	result = o:create_distribution_counts_over( 1 )
	assert_table_count( result, 1 )
	assert_equals( result[1].kindof, "bluray" )
	assert_equals( result[1].genre, 1009 )
	assert_equals( result[1].rating_id, 6 )
	assert_equals( result[1].count, 1 )

